document.addEventListener('paste',event=>{if(event.target.id!=='compose-editor'||collabEditor)return;event.preventDefault();const html=event.clipboardData.getData('text/html'),text=event.clipboardData.getData('text/plain');document.execCommand('insertHTML',false,html?safeHtml(html):e(text).replaceAll('\n','<br>'));scheduleDraftSave();});
document.addEventListener('keydown',event=>{const modalEl=document.querySelector('[role=dialog]');if(event.key==='Escape'){if(modalEl){event.preventDefault();closeModal();}else if(S.mobileOpen){S.mobileOpen=false;render();}return;}if(modalEl&&event.key==='Tab'){const nodes=[...modalEl.querySelectorAll('button:not(:disabled),input:not([type=hidden]),textarea,select,a[href],[contenteditable=true]')].filter(n=>n.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}return;}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();document.querySelector('#global-search')?.focus();return;}if((event.ctrlKey||event.metaKey)&&event.key==='Enter'&&S.draft){event.preventDefault();action('send').catch(error=>composeError(error.message));return;}if(event.target.matches('input,textarea,select,[contenteditable=true]')||modalEl)return;if(event.key==='Enter'&&event.target.dataset.action){event.preventDefault();action(event.target.dataset.action,event.target).catch(error=>notify(error.message));return;}const key=event.key.toLowerCase();if(key==='n')action('new');if(key==='r'&&S.view==='mail')action('reply');if(key==='e'&&S.view==='mail')action('archive');if(['j','k'].includes(key)&&S.view==='mail'){const messages=filteredMail(),index=messages.findIndex(m=>m.id===S.selected),next=messages[Math.max(0,Math.min(messages.length-1,index+(key==='j'?1:-1)))];if(next)action('open:'+next.id);}if(key==='?')action('help');});
window.addEventListener('beforeunload',event=>{if(S.draft?.dirty||S.draft?.busy||S.draft&&['saving','offline','expired'].includes(S.draft.liveStatus)){event.preventDefault();event.returnValue='';}});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['mail','calendar','people','tasks','files','team','settings'].includes(view)){S.view=view;render();}});
let workerSequence=0;const workerRequests=new Map();
function searchInWorker(query){if(!worker){worker=new Worker('./search-worker.js',{type:'module'});worker.onmessage=({data})=>{workerRequests.get(data.id)?.(data.ids);workerRequests.delete(data.id);};worker.onerror=()=>{for(const resolve of workerRequests.values())resolve(byKind('message').filter(m=>matches(m,S.query)).map(m=>m.id));workerRequests.clear();worker.terminate();worker=null;};}return new Promise(resolve=>{const id=++workerSequence;workerRequests.set(id,resolve);worker.postMessage({id,query,messages:byKind('message')});});}
let automationBusy=false;const reminded=new Set();async function background(){if(document.hidden||S.draft||automationBusy)return;automationBusy=true;try{if(runtime.connected){await runtime.flush();await load({quiet:true});return;}await load({quiet:true});for(const m of byKind('message').filter(m=>m.snoozedUntil&&new Date(m.snoozedUntil)<=new Date()))await update(m,{folder:'inbox',snoozedUntil:null});await runRules(true);for(const task of byKind('task').filter(t=>!t.done&&t.reminder&&new Date(t.reminder)<=new Date()))if(!reminded.has(task.id)){reminded.add(task.id);notify('Reminder: '+task.title);}}finally{automationBusy=false;}}
function registerTools(){if(!document.modelContext?.registerTool)return;const abort=new AbortController();window.addEventListener('pagehide',()=>abort.abort(),{once:true});const tools=[{name:'avenor_search_mail',description:'Search the current Avenor workspace without changing messages.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(typeof input?.query!=='string'||input.query.length>500)throw Error('A query up to 500 characters is required');return byKind('message').filter(m=>matches(m,input.query)).slice(0,50).map(({id,subject,from,date,read})=>({id,subject,from,date,read}));}},{name:'avenor_start_message',description:'Open a draft composer with a recipient and subject. Does not send the message.',inputSchema:{type:'object',properties:{to:{type:'string'},subject:{type:'string'}},required:['to','subject'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(typeof input?.to!=='string'||typeof input?.subject!=='string'||input.to.length>1000||input.subject.length>500)throw Error('Invalid recipient or subject');if(S.draft)throw Error('Close the current draft first');await compose();document.querySelector('#compose-to').value=input.to;document.querySelector('#compose-subject').value=input.subject;scheduleDraftSave();await saveDraft();return {draftId:S.draft.record.id,status:'draft'};}},{name:'avenor_create_task',description:'Create a task in the current workspace and display To Do.',inputSchema:{type:'object',properties:{title:{type:'string'},due:{type:'string'}},required:['title'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(typeof input?.title!=='string'||!input.title.trim()||input.title.length>500)throw Error('A task title is required');if(input.due&&!/^\d{4}-\d{2}-\d{2}$/.test(input.due))throw Error('Use YYYY-MM-DD for due');const t=await create('task',{title:input.title,due:input.due||'',done:false,myDay:true,important:false,steps:[]});S.view='tasks';render();return {id:t.id,title:t.title};}}];for(const tool of tools)Promise.resolve(document.modelContext.registerTool(tool,{signal:abort.signal})).catch(error=>console.warn('Agent tool unavailable',error.message));}
runtime.initialize().then(async()=>{await finishOidc();return load();}).then(()=>{registerTools();setInterval(()=>background().catch(()=>{}),runtime.connected?60000:8000);if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});});
function showServerLogin(){document.querySelector('#app').innerHTML=`<div class="boot server-boot"><span class="brand-mark">a</span><h1>Welcome to Avenor</h1><p>${e(runtime.server)}</p><form data-advanced="login" class="login-form">${field('Email','email','','email','required autocomplete="username"')}${field('Password','password','','password','required autocomplete="current-password"')}${field('Authenticator or recovery code (if enabled)','code','','text','autocomplete="one-time-code"')}<button class="primary" type="submit">Sign in</button><div class="form-error" role="alert"></div></form><div class="team-tools">${btn('oidc-login','Enterprise sign-in','shield','secondary')}${btn('register','Use an invitation','people','secondary')}${btn('server-disconnect','Use this device','back','secondary')}</div></div>`;}
function advancedModal(title,kind,body,button='Save'){modal(title,`<form data-advanced="${kind}" id="advanced-form">${body}<div class="form-error" role="alert"></div></form>`,`${btn('close-modal','Cancel',null,'secondary')}<button class="primary" type="submit" form="advanced-form">${e(button)}</button>`);}
function renderConnections(){return `<div class="settings-card"><h3>${runtime.connected?'Connected to your server':'Use Avenor anywhere'}</h3><p>${runtime.connected?e(runtime.server):'This GitHub Pages workspace saves on this device. Connect your Avenor server for internet mail, shared editing, invitations, and background processing.'}</p>${btn('server-connect',runtime.connected?'Change server':'Connect a server','globe','primary')}${runtime.connected?btn('server-disconnect','Disconnect','logout','secondary'):''}</div>${runtime.connected?`<div class="settings-card"><h3>Your email accounts</h3><p>Authorize a provider, or connect a mailbox using secure SMTP and IMAP. Secrets stay on your server.</p><div class="team-tools">${btn('oauth:microsoft','Microsoft 365','mail','secondary')}${btn('oauth:google','Google / Gmail','mail','secondary')}${btn('smtp-account','SMTP + IMAP','globe','secondary')}</div>${(S.providerStatus||[]).filter(p=>!p.configured).map(p=>`<p class="form-hint">${e(p.name||p.id||p.provider)}: ${e(p.reason||'Provider credentials are not configured on the server.')}</p>`).join('')}${(S.accounts||[]).map(a=>`<div class="member">${avatar(a.email,'blue')}<div><strong>${e(a.email)}</strong><p>${e(a.provider)} · ${e(a.status||'connected')}</p></div>${btn('sync-account:'+a.id,'Synchronize','refresh')}${btn('remove-account:'+a.id,'Disconnect account','trash')}</div>`).join('')||'<p class="form-hint">No email account connected yet.</p>'}</div>`:''}`;}
function renderSecurity(){if(!runtime.connected)return `<div class="settings-card"><h3>Server security</h3><p>Connect your Avenor server to manage two-factor authentication, mailbox delegation, retention, and audit records.</p>${btn('server-connect','Connect a server','globe','primary')}</div>`;return `<div class="settings-card"><h3>Sign-in protection</h3><p>Protect password sign-in with an authenticator app. Enterprise sign-in uses the policies of your configured identity provider.</p><div class="team-tools">${btn('setup-mfa','Set up two-factor authentication','shield','secondary')}${btn('revoke-sessions','Sign out all sessions','logout','secondary')}</div></div><div class="settings-card"><h3>Mailbox delegation</h3><p>Give another registered account read, edit, or send permission for your personal mailbox.</p>${btn('delegate-mailbox','Add delegate','people','primary')}${(S.delegates||[]).map(d=>`<div class="member"><div><strong>${e(d.name||d.email)}</strong><p>${e(d.email)} · ${e(JSON.parse(d.permissions).join(', '))}</p></div>${btn('revoke-delegate:'+d.email,'Revoke access','close')}</div>`).join('')}</div><div class="settings-card"><h3>Retention & legal hold</h3><p>Retention removes older items from normal access after the configured period. A legal hold prevents deletion and suspends retention.</p><form data-advanced="policy">${field('Retention days (0 disables)','retentionDays',S.policy?.retention_days||0,'number','min="0" max="36500"')}<label><input type="checkbox" name="legalHold" ${S.policy?.legal_hold?'checked':''}> Preserve records under a legal hold</label><button class="primary" style="display:block;margin-top:18px">Save policy</button><div class="form-error"></div></form></div>${runtime.user?.role==='admin'?`<div class="settings-card"><h3>Administration</h3><p>Create account invitations and export the audit log. The audit chain detects modification when compared against a trusted exported head; it does not confer regulatory certification.</p><div class="team-tools">${btn('invite-account','Invite an account','people','secondary')}${btn('manage-accounts','Manage accounts','settings','secondary')}${btn('export-audit','Export audit log','download','secondary')}</div></div>`:''}`;}
function renderSync(){return `<div class="settings-card"><h3>Offline synchronization</h3><p>Edits are stored before transmission. A conflicting edit stays in the queue until you review it; it is never silently overwritten.</p>${btn('sync-now','Sync now','refresh','primary')}${(S.pending||[]).map(p=>`<div class="rule-row"><div><h4>${e(p.method+' '+p.path)} · ${e(p.status)}</h4><p>${e(p.error||'Waiting to synchronize')}</p></div>${btn('review-conflict:'+p.id,'Review','edit')}</div>`).join('')||'<p class="form-hint">No pending record changes.</p>'}</div><div class="settings-card"><h3>Scheduled work</h3><p>${runtime.connected?'The server processes these jobs even when you close the browser.':'Connect a server to schedule mail and process work while this app is closed.'}</p>${(S.jobs||[]).map(j=>`<div class="rule-row"><div><h4>${e(j.type)} · ${e(j.status)}</h4><p>${e(new Date(j.runAt).toLocaleString())}${j.error?' · '+e(j.error):''}</p></div>${j.status==='pending'?btn('cancel-job:'+j.id,'Cancel job','close'):''}</div>`).join('')||'<p class="form-hint">No scheduled jobs.</p>'}</div>`;}
let accountLoading=false;async function loadAccounts(){if(!runtime.connected||accountLoading)return;accountLoading=true;try{const data=await api('accounts?scope='+encodeURIComponent(S.scope));S.accounts=data.accounts||[];S.providerStatus=data.providers||[];}catch{}finally{accountLoading=false;}}
function stopLive(){clearTimeout(liveRefreshTimer);liveUnsubscribe?.();liveUnsubscribe=null;liveScope=null;liveIdentity=null;live?.close();live=null;collabEditor=null;collabBinding=null;}
function showDraftLiveStatus(){const draft=S.draft,el=document.querySelector('#draft-status');if(!draft||!el||!draft.liveStatus)return;const labels={connecting:'Connecting shared draft…',ready:'Shared draft saved',saving:'Saving shared draft…',saved:'Shared draft saved',offline:'Offline · saving on this device…','offline-saved':'Saved on this device · waiting to sync',expired:'Session expired · reconnect to save',readonly:'Shared draft · read only',revoked:'Document access revoked',error:'Shared draft needs attention'};el.textContent=labels[draft.liveStatus]||draft.liveStatus;const others=draft.participants?.filter(person=>person.userId!==(S.user?.id||S.user?.userId))||[];if(others.length&&['ready','saved'].includes(draft.liveStatus))el.textContent+=' · '+others.map(person=>person.displayName).join(', ');}
function renderDeliveryStatus(message){if(message.delivery!=='partial')return '';const recipients=list=>(list||[]).map(value=>typeof value==='string'?value:value.address||value.email||'Unknown address').map(e).join(', ');return `<div class="error-inline" role="status" style="margin-bottom:22px"><strong>Accepted for some recipients</strong><p style="margin:8px 0">Accepted: ${recipients(message.accepted)||'See your provider’s delivery status'}</p><p style="margin:8px 0">Rejected: ${recipients(message.rejected)||'See your provider’s delivery status'}</p><p style="margin:8px 0 0">Review the rejected addresses before writing a new message to those recipients.</p></div>`;}
function handleLiveStatus(status,details={}){S.liveStatus=status;const globalLabels={connecting:'Connecting live updates…',connected:'Live · changes synchronized',offline:'Offline · cached workspace',expired:'Session expired · sign in again'};if(globalLabels[status])document.querySelector('#sync-label')?.replaceChildren(document.createTextNode(globalLabels[status]));const draft=S.draft;if(!draft||details.recordId&&details.recordId!==draft.record?.id||details.scope&&details.scope!==S.scope)return;if(status==='document-ready'||status==='permission'){draft.liveStatus=details.readOnly?'readonly':details.pending?'saving':'ready';draft.accessRevoked=false;lockComposer(composerLocked);}else if(['connecting','offline','offline-saved','expired','saving','saved','error','revoked'].includes(status)){draft.liveStatus=status;if(status==='expired'||status==='revoked'){draft.accessRevoked=true;lockComposer(composerLocked);}if(status==='error'&&details.message)composeError(details.message);}showDraftLiveStatus();}
function connectLive(){if(!runtime.connected||!runtime.token)return null;const identity=runtime.server+':'+runtime.token;if(live&&liveIdentity!==identity)stopLive();if(!live){liveIdentity=identity;live=new LiveClient({url:runtime.server.replace(/^http/,'ws')+'/api/live',getToken:()=>runtime.token,onChange:(event,scope)=>{if(scope===S.scope&&!S.draft){clearTimeout(liveRefreshTimer);liveRefreshTimer=setTimeout(()=>{if(scope===S.scope&&!S.draft)load({quiet:true});},150);}if(scope===S.scope&&event.type==='permissions-changed')notify('Workspace permissions changed');},onPresence:({recordId,scope,participants})=>{if(S.draft?.record?.id!==recordId||S.scope!==scope)return;S.draft.participants=participants;showDraftLiveStatus();},onStatus:handleLiveStatus});live.connect().catch(()=>{});}if(S.scope&&liveScope!==S.scope){liveUnsubscribe?.();liveScope=S.scope;liveUnsubscribe=live.subscribe(S.scope);}return live;}
async function bindCollaborativeEditor(){if(!runtime.connected||!S.draft?.record||S.draft.record.pending||collabEditor)return;if(collabBinding)return collabBinding;const draft=S.draft,scope=S.scope,element=document.querySelector('#compose-editor'),client=connectLive();if(!client||!element)return;draft.liveStatus='connecting';showDraftLiveStatus();const pending=(async()=>{await client.connect();if(S.draft!==draft||S.scope!==scope||!element.isConnected||live!==client)return;const binding=client.attachEditor({element,recordId:draft.record.id,scope,onChange:(html,meta)=>{if(S.draft!==draft)return;draft.data.body=html;if(draft.record){draft.record.body=html;const saved=get(draft.record.id);if(saved)saved.body=html;}if(!meta.remote){draft.liveStatus='saving';showDraftLiveStatus();}}});collabEditor=binding;binding.setLocked(composerLocked);await binding.ready;if(S.draft!==draft||collabEditor!==binding){binding();return;}draft.liveStatus=binding.isReadOnly()?'readonly':binding.hasPending()?'saving':'ready';lockComposer(composerLocked);showDraftLiveStatus();})();collabBinding=pending;try{await pending;}catch(error){if(S.draft===draft){draft.liveStatus='error';showDraftLiveStatus();composeError(error.message);}throw error;}finally{if(collabBinding===pending)collabBinding=null;}}
async function showNotifications(){const data=await api('notifications?scope='+encodeURIComponent(S.scope));modal('Notifications',`<div>${(data.notifications||[]).map(n=>`<div class="rule-row"><div><h4>${e(n.title)}</h4><p>${e(fmt(n.created,{month:'short',day:'numeric'}))} · ${e(n.type)}</p></div>${!n.read?btn('read-notification:'+n.id,'Mark read','check'):''}</div>`).join('')||empty('bell','You’re up to date','Server reminders and invitation responses appear here.')}</div>`);}
async function advancedAction(name,value){switch(name){
 case 'server-connect':advancedModal('Connect your Avenor server','connect',field('Server address','url',runtime.server||'','url','required placeholder="https://mail.example.com"')+'<p class="form-hint">Run the included server on your hosting provider, then enter its HTTPS address. The GitHub Pages interface will connect directly to it.</p>','Connect');break;
 case 'server-disconnect':if(!runtime.connected){await advancedAction('server-connect');break;}if(!await closeModal())return true;stopLive();await runtime.disconnect();S.user=null;S.scope=null;S.records=[];S.accounts=[];S.selected=null;S.lastFingerprint='';await load();break;
 case 'register':advancedModal('Create your account','register',field('Name','name','','text','required')+field('Invitation code','invite','','text','required')+field('Password (12 or more characters)','password','','password','required minlength="12"'),'Create account');break;
 case 'oidc-login':{const bytes=crypto.getRandomValues(new Uint8Array(32)),verifier=btoa(String.fromCharCode(...bytes)).replaceAll('+','-').replaceAll('/','_').replaceAll('=',''),hash=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))),challenge=btoa(String.fromCharCode(...hash)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');sessionStorage.setItem('avenor-oidc-verifier',verifier);const data=await runtime.direct('auth/oidc/start',{method:'POST',body:{challenge}});location.assign(data.url);break;}
 case 'oauth':{const data=await api('oauth/'+value+'/start',{method:'POST',body:'{}'});location.assign(data.url);break;}
 case 'smtp-account':advancedModal('Connect SMTP and IMAP','smtp',field('Email address','email','','email','required')+field('Display name','displayName',S.user.name)+`<div class="form-grid">${field('SMTP host','smtpHost','','text','required placeholder="smtp.example.com"')}${field('SMTP port','smtpPort',465,'number','required')}${field('IMAP host','imapHost','','text','required placeholder="imap.example.com"')}${field('IMAP port','imapPort',993,'number','required')}</div>`+field('Username','username',S.user.email,'text','required')+field('Password or app password','password','','password','required')+'<p class="form-hint">Port 465 uses implicit TLS. Port 587 requires STARTTLS. IMAP 993 uses implicit TLS; port 143 requires STARTTLS. Credentials are encrypted on your server.</p>','Connect account');break;
 case 'sync-account':notify('Synchronizing your mailbox…');{const result=await api('accounts/'+value+'/sync',{method:'POST',body:'{}'});await load();notify(result.count+' mailbox changes synchronized');}break;
 case 'remove-account':modal('Disconnect this email account?',`<p>Provider access credentials will be removed. Previously imported messages remain in your workspace.</p>`,btn('close-modal','Cancel',null,'secondary')+btn('confirm-remove-account:'+value,'Disconnect',null,'primary'));break;
 case 'confirm-remove-account':await api('accounts/'+value,{method:'DELETE'});await loadAccounts();await closeModal();render();notify('Email account disconnected');break;
 case 'schedule-send':{if(!S.draft)return;const record=await flushDraft();if(record.pending)throw Error('Synchronize this draft before scheduling');S.schedulingDraft={id:record.id,version:record.version,accountId:S.draft.data.accountId||''};S.draft=null;collabEditor?.();collabEditor=null;advancedModal('Schedule this message','schedule',field('Send at','runAt',dateKey(new Date(Date.now()+86400000))+'T09:00','datetime-local','required')+'<p class="form-hint">Your server sends this message at the selected time. Ambiguous provider outcomes require review before any retry.</p>','Schedule');break;}
 case 'send-invitations':{const ev=get(value);S.invitingEvent=ev;advancedModal('Send calendar invitations','invitations',`<p class="form-hint">Email invitations for “${e(ev.title)}” to ${e(ev.attendees||'the attendee list')}.</p>`+select('Sending account','accountId',(S.accounts||[]).map(a=>[a.id,a.email]),S.accounts?.[0]?.id)+select('Invitation type','method',[['REQUEST','Invite or update'],['CANCEL','Cancel meeting']],'REQUEST'),'Queue invitations');break;}
 case 'setup-mfa':advancedModal('Set up two-factor authentication','mfa-setup',field('Confirm password','password','','password','required'),'Continue');break;
 case 'revoke-sessions':if(!await closeModal())return true;await api('auth/sessions/revoke',{method:'POST',body:'{}'});stopLive();await runtime.disconnect();location.reload();break;
 case 'delegate-mailbox':advancedModal('Delegate your mailbox','delegate',field('Registered account email','email','','email','required')+'<div class="team-tools"><label><input type="checkbox" name="read" checked disabled> Read</label><label><input type="checkbox" name="write"> Edit</label><label><input type="checkbox" name="send"> Send</label></div>','Grant access');break;
 case 'revoke-delegate':await api('delegations',{method:'DELETE',body:JSON.stringify({email:value})});await loadAdvancedSettings();render();notify('Delegate access revoked');break;
 case 'invite-account':advancedModal('Invite an account','account-invite',field('Email address','email','','email','required'),'Create invitation');break;
 case 'export-audit':download('avenor-audit.json',JSON.stringify(await api('audit'),null,2),'application/json');break;
 case 'sync-now':await runtime.flush();await load();await loadAdvancedSettings();render();notify('Synchronization checked');break;
 case 'cancel-job':await api('jobs/'+value,{method:'DELETE'});await loadAdvancedSettings();render();notify('Scheduled job cancelled');break;
 case 'review-conflict':{const entry=(await runtime.pending()).find(p=>p.id===value);S.reviewEntry=entry;S.reviewLatest=null;if(!entry)return;if(entry.body?.id){let page=await runtime.direct('data?scope='+encodeURIComponent(S.scope));S.reviewLatest=page.records.find(r=>r.id===entry.body.id);while(!S.reviewLatest&&page.nextCursor){page=await runtime.direct('data?scope='+encodeURIComponent(S.scope)+'&cursor='+encodeURIComponent(page.nextCursor));S.reviewLatest=page.records.find(r=>r.id===entry.body.id);}}modal('Review pending change',`<p class="form-hint">${e(entry.error||'This change is waiting to synchronize.')}</p><h4>Your pending change</h4><pre class="pending-json">${e(JSON.stringify(entry.body,null,2))}</pre>${S.reviewLatest?`<h4>Current server version ${S.reviewLatest.version}</h4><pre class="pending-json">${e(JSON.stringify(Object.fromEntries(Object.keys(entry.body.patch||{}).map(k=>[k,S.reviewLatest[k]])),null,2))}</pre>`:''}<p class="form-hint">Review both versions. Applying your change replaces the listed fields on the reviewed server version. Another intervening change will still be detected.</p>`,btn('close-modal','Keep pending',null,'secondary')+btn('discard-pending:'+value,'Discard pending edit',null,'secondary')+(entry.method==='PATCH'&&S.reviewLatest?btn('resolve-pending:'+value,'Apply reviewed change',null,'primary'):''));break;}
 case 'resolve-pending':{const entry=S.reviewEntry,latest=S.reviewLatest;if(!entry||entry.id!==value||!latest)throw Error('Review the current server version first');await runtime.transport.store.resolveConflict(value,{body:{...entry.body,version:latest.version},baseVersion:latest.version});await runtime.flush();await closeModal();await load();await loadAdvancedSettings();render();notify('Reviewed change submitted; unresolved changes remain in the queue');break;}
 case 'member-role':{const member=S.members.find(m=>m.id===value);if(!member)return;S.roleMember=member;advancedModal('Change workspace role','member-role',`<p>${e(member.name)} · ${e(member.email)}</p><label>Role<select name="role"><option value="viewer" ${member.role==='viewer'?'selected':''}>Viewer — read only</option><option value="editor" ${member.role==='editor'?'selected':''}>Editor — edit shared records</option></select></label>`);break;}
 case 'manage-accounts':{const result=await api('auth/users');S.accountList=result.users;modal('Accounts',result.users.map(u=>`<div class="member"><div><strong>${e(u.name)}</strong><p>${e(u.email)} · ${e(u.role)} · ${u.disabled?'Disabled':'Active'}</p></div>${u.id!==S.user.id?btn('edit-account:'+u.id,'Manage account','settings'):''}</div>`).join(''));break;}
 case 'edit-account':{const account=S.accountList.find(u=>u.id===value);if(!account)return;S.editAccount=account;advancedModal('Account access','account-access',`<p>${e(account.email)}</p><label>Role<select name="role"><option value="user" ${account.role==='user'?'selected':''}>User</option><option value="admin" ${account.role==='admin'?'selected':''}>Administrator</option></select></label><label><input type="checkbox" name="disabled" ${account.disabled?'checked':''}> Disable this account and revoke its sessions</label>`);break;}
 case 'discard-pending':await runtime.transport.store.removePending(value);await closeModal();await load();await loadAdvancedSettings();render();notify('Pending edit discarded; server copy restored');break;
 case 'read-notification':await api('notifications',{method:'PATCH',body:JSON.stringify({id:value,read:true})});await closeModal();await showNotifications();break;
 default:return false;
 }return true;}
async function loadAdvancedSettings(){S.pending=await runtime.pending();if(runtime.connected){const results=await Promise.allSettled([api('jobs'),api('delegations'),api('policies?scope='+encodeURIComponent(S.scope))]);S.jobs=results[0].status==='fulfilled'?results[0].value.jobs||[]:[];S.delegates=results[1].status==='fulfilled'?results[1].value.delegations||[]:[];S.policy=results[2].status==='fulfilled'?results[2].value.policy:null;}await loadAccounts();}
async function advancedSubmit(form){const kind=form.dataset.advanced,v=Object.fromEntries(new FormData(form)),button=form.querySelector('[type=submit]')||document.querySelector('[form=advanced-form]');if(button)button.disabled=true;try{switch(kind){
 case 'connect':if(!await closeModal())return;stopLive();await runtime.connect(v.url);S.user=null;S.scope=null;showServerLogin();break;
 case 'login':await runtime.login(v.email,v.password,v.code);S.user=null;S.scope=null;S.lastFingerprint='';await load();break;
 case 'register':{const result=await runtime.direct('auth/register',{method:'POST',body:v});await runtime.acceptSession(result);await closeModal();S.user=null;S.scope=null;S.lastFingerprint='';await load();break;}
 case 'smtp':await api('accounts',{method:'POST',body:JSON.stringify({provider:'smtp',email:v.email,displayName:v.displayName,smtp:{host:v.smtpHost,port:Number(v.smtpPort),secure:Number(v.smtpPort)===465,user:v.username,password:v.password},imap:{host:v.imapHost,port:Number(v.imapPort),secure:Number(v.imapPort)===993,user:v.username,password:v.password}})});await closeModal();await loadAccounts();render();notify('Account connected');break;
 case 'schedule':await api('jobs',{method:'POST',body:JSON.stringify({type:'send',recordId:S.schedulingDraft.id,version:S.schedulingDraft.version,accountId:S.schedulingDraft.accountId,runAt:new Date(v.runAt).toISOString()})});await closeModal();await load();notify('Message scheduled on your server');break;
 case 'invitations':{if(!v.accountId)throw Error('Connect an email account first.');await api('invitations',{method:'POST',body:JSON.stringify({eventId:S.invitingEvent.id,version:S.invitingEvent.version,accountId:v.accountId,method:v.method})});await closeModal();await load();notify('Calendar invitations queued');break;}
 case 'mfa-setup':{const result=await api('auth/mfa/setup',{method:'POST',body:JSON.stringify(v)});advancedModal('Add Avenor to your authenticator','mfa-confirm',`<p class="form-hint">Enter this secret in your authenticator, then confirm a six-digit code. Keep the secret private.</p><code class="setup-secret">${e(result.secret)}</code><a href="${e(result.uri)}">Open authenticator</a>`+field('Authenticator code','code','','text','required pattern="[0-9]{6}"'),'Enable');break;}
 case 'mfa-confirm':{const result=await api('auth/mfa/confirm',{method:'POST',body:JSON.stringify(v)});modal('Save your recovery codes',`<p class="form-hint">Two-factor authentication is enabled. Each recovery code works once; keep them somewhere safe.</p><pre class="pending-json">${e(result.recoveryCodes.join('\n'))}</pre>`,btn('close-modal','Done',null,'primary'));break;}
 case 'delegate':await api('delegations',{method:'POST',body:JSON.stringify({email:v.email,permissions:['read',...(v.write?['write']:[]),...(v.send?['send']:[])]})});await closeModal();await loadAdvancedSettings();render();notify('Mailbox access granted');break;
 case 'policy':await api('policies',{method:'POST',body:JSON.stringify({scope:S.scope,retentionDays:Number(v.retentionDays),legalHold:!!v.legalHold})});await loadAdvancedSettings();notify('Retention policy saved');break;
 case 'member-role':await api('team/role',{method:'POST',body:JSON.stringify({team:S.scope.slice(5),user:S.roleMember.id,role:v.role})});await closeModal();await load();notify('Workspace role updated');break;
 case 'account-access':await api('auth/users',{method:'PATCH',body:JSON.stringify({id:S.editAccount.id,role:v.role,disabled:form.elements.disabled.checked})});await closeModal();await advancedAction('manage-accounts');notify('Account access updated');break;
 case 'account-invite':{const result=await api('auth/invitations',{method:'POST',body:JSON.stringify(v)});modal('Account invitation',`<p class="form-hint">Give this one-time code to ${e(result.email)}. It expires in seven days and creates only that email’s account.</p><textarea rows="3" readonly id="invite-code" style="width:100%">${e(result.invite)}</textarea>`,btn('copy-invite','Copy invitation','clip','primary'));break;}
 }}catch(error){const box=form.querySelector('.form-error');if(box)box.textContent=error.message;else notify(error.message);}finally{if(button)button.disabled=false;}}
async function finishOidc(){const match=location.hash.match(/^#auth=(.+)$/);if(!match)return;const code=decodeURIComponent(match[1]),verifier=sessionStorage.getItem('avenor-oidc-verifier');history.replaceState(null,'',location.pathname);sessionStorage.removeItem('avenor-oidc-verifier');const result=await runtime.direct('auth/exchange',{method:'POST',body:{code,verifier}});await runtime.acceptSession(result);}
window.addEventListener('avenor:remote-change',()=>{if(!S.draft)load({quiet:true});});
window.addEventListener('avenor:status',({detail})=>{const el=document.querySelector('#sync-label');if(el)el.textContent=detail.status==='online'?'Connected · saved':detail.status==='offline'?'Offline · cached workspace':'Pending edits · review sync';});
